public boolean validate()
{
    boolean ret;

    ret = next validate()
        && this.AIBIsFantasyBook();

        return ret;
}

private boolean AIBIsFantasyBook()
{
    SalesTable salesTable = this.dataSource().cursor();

    if(AIBBookTable::findRecId(salesTable.AIBBookTable).Genre != AIBGenreEnum::Fantasy)
    {
        return checkFailed("@ITFormacion:YouMustSelectFantasyBooks");
    }
    return true;

}
